mkdir -p /tmp/gate-test && cat > /tmp/gate-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g2-2/bot.mjs';

const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// Tokyo is UTC+9. Helper: build a Date from a Tokyo wall-clock time.
const tokyo = (iso) => new Date(`${iso}+09:00`);

// 1. Daytime allowed, result shape
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00')), { allowed: true, reason: null });
}
// 2. Quiet hours block, both sides of midnight, boundaries
{
  const g = createPushGate();
  const q = { allowed: false, reason: 'quiet_hours' };
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T22:00')), q);   // start inclusive
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T00:30')), q);   // after midnight
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T06:59')), q);
  assert.deepEqual(g.attempt(base, tokyo('2026-10-23T07:00')), { allowed: true, reason: null }); // end exclusive
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T21:59')), { allowed: true, reason: null });
}
// 3. Quiet hours use the user's zone, not UTC or the server zone
{
  const g = createPushGate();
  // 23:00 in Tokyo = 14:00 UTC; user in New York sees 09:00 -> allowed; in Tokyo quiet
  const ny = { ...base, id: 'u_ny', timeZone: 'America/New_York' };
  assert.equal(g.attempt(ny, new Date('2026-10-22T14:00:00Z')).allowed, true);
  assert.equal(g.attempt(base, new Date('2026-10-22T14:00:00Z')).reason, 'quiet_hours');
}
// 4. Daily cap counts local day, blocked not counted, reason code
{
  const g = createPushGate();
  const u = { ...base, quietStart: '00:00', quietEnd: '00:00' }; // no quiet period
  assert.equal(g.attempt(u, tokyo('2026-10-22T08:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T09:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T10:00')).allowed, true);
  assert.deepEqual(g.attempt(u, tokyo('2026-10-22T11:00')), { allowed: false, reason: 'daily_cap_reached' });
  // New local day resets
  assert.equal(g.attempt(u, tokyo('2026-10-23T00:01')).allowed, true);
}
// 5. Day is local, not UTC: 08:00 Tokyo Oct 23 = 23:00 UTC Oct 22; UTC-day would merge them
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(g.attempt(u, new Date('2026-10-22T16:00:00Z')).allowed, true); // Tokyo Oct 23 01:00
  assert.equal(g.attempt(u, new Date('2026-10-22T23:00:00Z')).allowed, true); // Tokyo Oct 23 08:00 -> same local day -> cap
}
EOF
cat >> /tmp/gate-test/test.mjs <<'EOF'
// 5b. (correction of 5) same local day must be capped
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(g.attempt(u, new Date('2026-10-22T16:00:00Z')).allowed, true);
  assert.deepEqual(g.attempt(u, new Date('2026-10-22T23:00:00Z')), { allowed: false, reason: 'daily_cap_reached' });
}
// 6. Per-call settings: cap and quiet change between calls
{
  const g = createPushGate();
  const u = { ...base, quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T10:00')).allowed, true);
  assert.equal(g.attempt({ ...u, dailyCap: 2 }, tokyo('2026-10-22T11:00')).allowed, true);
  assert.equal(g.attempt({ ...u, dailyCap: 0 }, tokyo('2026-10-22T12:00')).reason, 'daily_cap_reached');
}
// 7. Independent gates and independent users
{
  const a = createPushGate(); const b = createPushGate();
  const u = { ...base, dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(a.attempt(u, tokyo('2026-10-22T10:00')).allowed, true);
  assert.equal(b.attempt(u, tokyo('2026-10-22T10:00')).allowed, true);
  assert.equal(a.attempt({ ...u, id: 'other' }, tokyo('2026-10-22T10:00')).allowed, true);
}
// 8. Quiet check runs before cap; quiet-blocked attempt is not counted
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T23:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, tokyo('2026-10-23T08:00')).allowed, true); // cap not used up by the blocked one
}
// 9. Invalid input throws
{
  const g = createPushGate();
  assert.throws(() => g.attempt(base, new Date('nope')), TypeError);
  assert.throws(() => g.attempt({ ...base, quietStart: '24:00' }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: -1 }, new Date()), TypeError);
  assert.throws(() => g.attempt({ ...base, timeZone: 'Mars/Olympus' }, new Date()), RangeError);
}
// 10. Half-hour zone and DST-free check
{
  const g = createPushGate();
  const kolkata = { id: 'u_in', timeZone: 'Asia/Kolkata', quietStart: '22:00', quietEnd: '07:00', dailyCap: 5 };
  // 22:30 IST = 17:00 UTC
  assert.equal(g.attempt(kolkata, new Date('2026-10-22T17:00:00Z')).reason, 'quiet_hours');
}
// 11. Performance smoke: many users, cap reached
{
  const g = createPushGate();
  const t0 = performance.now();
  for (let i = 0; i < 20000; i++) {
    g.attempt({ ...base, id: `u${i % 500}`, quietStart: '00:00', quietEnd: '00:00', dailyCap: 3 }, tokyo('2026-10-22T12:00'));
  }
  console.log(`20k attempts: ${(performance.now() - t0).toFixed(1)} ms`);
}
console.log('all checks passed');
EOF
cd /tmp/gate-test && node test.mjs
